from batch07 import *
start('ipv4','IPv4 — VLSM i granice podsieci','1.6',['https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13790-8.html','https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13788-3.html'],True)
q('Podział /24 na /28','Ile rozłącznych podsieci /28 mieści się w jednym /24?','16',['4|Różnica czterech bitów oznacza 2^4, nie cztery podsieci.','8|Osiem odpowiada różnicy trzech bitów.','32|Trzydzieści dwa odpowiada różnicy pięciu bitów.'],'Na identyfikację podsieci przeznaczono dodatkowe cztery bity: 2^4 = 16.')
q('Granica /23','Jaki adres sieci ma host 172.16.7.200/23?','172.16.6.0',['172.16.7.0|/23 zaczyna blok na parzystym trzecim oktecie.','172.16.7.128|To granica /25, nie /23.','172.16.8.0|Ten adres należy do następnego bloku /23.'],'Maska /23 obejmuje dwa kolejne zakresy /24, tutaj trzeci oktet 6–7.')
c('Interfejs w dużym LAN','Przypisz pierwszy użyteczny adres sieci 10.44.8.0/22 i właściwą maskę.','R1(config-if)# ip address {{b0}} {{b1}}',[(['10.44.8.1'],'ipv4'),(['255.255.252.0'],'ipv4')],'Blok /22 ma 1024 adresy; typowy pierwszy host jest o jeden większy od adresu sieci.')
q('Nieprawidłowa brama','PC ma 192.168.5.129/25. Która propozycja jest adresem broadcast jego podsieci i nie może być zwykłą bramą?','192.168.5.255',['192.168.5.130|To użyteczny adres hosta w tej podsieci.','192.168.5.200|To użyteczny adres hosta w tej podsieci.','192.168.5.254|To ostatni użyteczny adres, nie broadcast.'],'Podsieć .128/25 kończy się broadcastem .255.')
c('Łącze /31','Obie strony obsługują /31 na łączu point-to-point. Peer ma 192.0.2.10/31. Ustaw drugi adres i maskę.','R1(config-if)# ip address {{b0}} {{b1}}',[(['192.0.2.11'],'ipv4'),(['255.255.255.254'],'ipv4')],'Na obsługiwanym łączu /31 oba adresy służą końcom łącza; nie odejmuje się sieci i broadcastu jak w zwykłym LAN.')
q('VLSM i kolejność','Masz przydzielić podsieci na 100, 50 i 20 hostów z jednego /24. Jaka strategia upraszcza poprawne wyrównanie bloków?','Przydzielać od największej wymaganej podsieci',['Zawsze zaczynać od najmniejszej bez kontroli wyrównania|Może utrudnić pozostawienie dużego spójnego bloku.','Nadać wszystkim tę samą podsieć|To nie rozdziela wymaganych sieci.','Użyć /30 dla każdej grupy|/30 nie pomieści tych liczb hostów.'],'Największe bloki jako pierwsze ułatwiają unikanie nakładania i fragmentacji przestrzeni adresowej.')
q('Minimalny LAN dla 200','Jaki najdłuższy prefiks zwykłej podsieci IPv4 pomieści 200 hostów?','/24',['/25|/25 zapewnia tylko 126 typowych adresów hostów.','/26|/26 zapewnia tylko 62 hosty.','/27|/27 zapewnia tylko 30 hostów.'],'/24 daje 254 adresy hostów; ciaśniejszy /25 jest za mały.')
q('Nakładanie VLSM','Czy 10.1.0.0/25 i 10.1.0.64/26 można użyć jako dwóch rozłącznych LAN-ów w tej samej tablicy routingu?','Nie, drugi blok jest zawarty w pierwszym',['Tak, ponieważ maski są różne|Różne długości nie gwarantują rozłączności.','Tak, bo zaczynają się od różnych ostatnich oktetów|Zakresy nadal się nakładają.','Tak, o ile oba mają DHCP|DHCP nie usuwa konfliktu planu adresacji.'],'Pierwszy zakres obejmuje .0–.127, a drugi .64–.127.')
c('VLSM: 100 i 50 hostów','Z 192.168.80.0/24 wydziel kolejno minimalne bloki: od .0 dla 100 hostów, potem od .128 dla 50. Na dwóch interfejsach użyj pierwszych hostów.','R1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip address {{b0}} {{b1}}\nR1(config-if)# exit\nR1(config)# interface GigabitEthernet0/1\nR1(config-if)# ip address {{b2}} {{b3}}',[(['192.168.80.1'],'ipv4'),(['255.255.255.128'],'ipv4'),(['192.168.80.129'],'ipv4'),(['255.255.255.192'],'ipv4')],'100 hostów wymaga /25, a 50 hostów /26; drugi blok zaczyna się po pierwszym.')
q('Adres na granicy','Do której sieci /26 należy 192.168.90.192?','192.168.90.192/26',['192.168.90.128/26|Ten blok kończy się na .191.','192.168.90.64/26|Ten blok kończy się na .127.','192.168.90.0/26|Ten blok kończy się na .63.'],'Granice /26 występują co 64 adresy; .192 jest adresem sieci czwartego bloku.')
c('Usuń nakładający adres','Na G0/1 błędnie ustawiono 10.1.0.65/26, nakładające się na LAN 10.1.0.0/25. Usuń dokładnie ten adres i ustaw pierwszy host wolnego 10.1.0.128/26.','R1(config-if)# no ip address {{b0}} 255.255.255.192\nR1(config-if)# ip address {{b1}} {{b2}}',[(['10.1.0.65'],'ipv4'),(['10.1.0.129'],'ipv4'),(['255.255.255.192'],'ipv4')],'Nowy zakres .128–.191 nie nakłada się na .0–.127.')
q('Podsumowanie czterech /24','Jaki jeden prefiks dokładnie obejmie 10.20.4.0/24, 10.20.5.0/24, 10.20.6.0/24 i 10.20.7.0/24?','10.20.4.0/22',['10.20.4.0/23|Obejmuje tylko dwa z czterech bloków.','10.20.0.0/22|Obejmuje zakresy trzeciego oktetu 0–3.','10.20.0.0/21|Zawiera także niepodane zakresy 0–3.'],'Cztery wyrównane /24 można połączyć w /22 obejmujące dokładnie trzeci oktet 4–7.')
q('Sumaryzacja z luką','Czy 10.2.0.0/24 i 10.2.2.0/24 da się połączyć w jeden prefiks obejmujący dokładnie tylko te dwa bloki?','Nie, pojedynczy prefiks obejmuje ciągły wyrównany zakres',['Tak, 10.2.0.0/23|Ten prefiks obejmuje .0 i .1, nie .2.','Tak, 10.2.2.0/23|Ten prefiks obejmuje .2 i .3, nie .0.','Tak, 10.2.0.0/22 bez innych adresów|/22 obejmuje także .1 i .3.'],'Agregat może obejmować nieprzydzielone przestrzenie; trzeba rozumieć jego rzeczywisty zakres.')
q('Wspólna podsieć?','Host A: 10.10.1.10/23, host B: 10.10.2.10/23. Czy według obu masek są w tej samej podsieci?','Nie',['Tak, oba mają początek 10.10|Dwa pierwsze oktety nie wystarczają przy /23.','Tak, bo ostatni oktet to 10|Numer hosta nie wyznacza podsieci.','Tak, bo adresy są prywatne|Adresacja prywatna nadal jest dzielona na podsieci.'],'A należy do 10.10.0.0/23, B do 10.10.2.0/23.')
c('Trzy minimalne LAN-y','Dla 60, 30 i 14 hostów wybierz maski dla bloków zaczynających się kolejno 10.60.0.0, .64 i .96. Pierwsze adresy wpisano.','R1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip address 10.60.0.1 {{b0}}\nR1(config-if)# exit\nR1(config)# interface GigabitEthernet0/1\nR1(config-if)# ip address 10.60.0.65 {{b1}}\nR1(config-if)# exit\nR1(config)# interface GigabitEthernet0/2\nR1(config-if)# ip address 10.60.0.97 {{b2}}',[(['255.255.255.192'],'ipv4'),(['255.255.255.224'],'ipv4'),(['255.255.255.240'],'ipv4')],'Potrzeba odpowiednio /26, /27 i /28; zakresy kończą się na .63, .95 i .111.')
q('Pomyłka /30','Na łączu 198.51.100.8/30 wybrano adres 198.51.100.11. Co jest nie tak?','To adres broadcast tego /30',['To pierwszy użyteczny host|Pierwszym hostem jest .9.','To adres sieci|Adresem sieci jest .8.','Nic, każdy z czterech adresów jest zwykłym hostem|W typowym /30 dwa adresy mają specjalne role.'],'Użyteczne końce zwykłego /30 to .9 i .10; .11 jest broadcastem.')
c('Adres końca i loopback','Peer ma 198.51.100.9/30. Ustaw drugi koniec na G0/0 oraz loopback 10.255.9.9 jako /32.','R1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip address {{b0}} {{b1}}\nR1(config-if)# exit\nR1(config)# interface Loopback0\nR1(config-if)# ip address 10.255.9.9 {{b2}}',[(['198.51.100.10'],'ipv4'),(['255.255.255.252'],'ipv4'),(['255.255.255.255'],'ipv4')],'Łącze /30 i loopback /32 mają inne potrzeby adresowe; dobiera się maskę do roli.')
q('Rezerwa adresów','W /27 trzeba pomieścić 29 stacji i jedną bramę, bez innych adresów zarezerwowanych. Czy się zmieszczą?','Tak, dokładnie 30 adresów hostów',['Nie, /27 ma tylko 28 hostów|Typowy /27 ma 30 użytecznych adresów.','Tak, pozostaną dwa wolne hosty|Sieć i broadcast nie są wolnymi adresami hostów.','Nie, brama nie może mieć IP z tej podsieci|Brama LAN zwykle ma adres z podsieci hostów.'],'2^5 − 2 = 30, czyli wystarcza dokładnie na podane urządzenia, bez zapasu.')
end()
